/**
 * Report PDF assets, embedded as base64 so they load in any runtime.
 *
 * Vercel serverless functions can't reliably read files from `public/` via
 * `fs`, so the product logo shown at the top of every generated review report
 * (`lib/okrAllyReport.ts`) is inlined here instead, one per brand.
 *
 * Source PNGs in `Scripts/okr-ally/brand-assets/` (`okr-ally-logo.png`,
 * `Goal Ally.png`), auto-cropped to the logomark + wordmark (dropping the
 * surrounding transparent / white margin), flattened onto white, downscaled to
 * 1000px wide and re-encoded as JPEG q82 — ~23-28 KB each, keeping the finished
 * PDF well under 150 KB. Reference copies of the cropped files also live at
 * `public/okr-ally/report-logo.jpg` and `public/goal-ally/report-logo.jpg`.
 */

/** Intrinsic pixel size of the embedded logo (for aspect-ratio math). */
export const REPORT_LOGO_W = 1000
export const REPORT_LOGO_H = 263

/** `data:` URI — pass straight to jsPDF `doc.addImage(REPORT_LOGO_JPEG, 'JPEG', ...)`. */
export const REPORT_LOGO_JPEG =
  'data:image/jpeg;base64,'

/** Intrinsic pixel size of the embedded Goal Ally logo (for aspect-ratio math). */
export const REPORT_GOAL_LOGO_W = 1000
export const REPORT_GOAL_LOGO_H = 333

/** `data:` URI — pass straight to jsPDF `doc.addImage(REPORT_GOAL_LOGO_JPEG, 'JPEG', ...)`. */
export const REPORT_GOAL_LOGO_JPEG =
  'data:image/jpeg;base64,'
